result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/metrics.py", "content": """"Forecast accuracy metrics."""
import numpy as np


def mae(y_true, y_pred) -> float:
    y_true, y_pred = np.asarray(y_true, float), np.asarray(y_pred, float)
    return float(np.mean(np.abs(y_true - y_pred)))


def rmse(y_true, y_pred) -> float:
    y_true, y_pred = np.asarray(y_true, float), np.asarray(y_pred, float)
    return float(np.sqrt(np.mean((y_true - y_pred) ** 2)))


def smape(y_true, y_pred) -> float:
    """Symmetric MAPE in percent: mean(|y - yhat| / (0.5*(|y| + |yhat|))) * 100."""
    y_true, y_pred = np.asarray(y_true, float), np.asarray(y_pred, float)
    denom = 0.5 * (np.abs(y_true) + np.abs(y_pred))
    return float(np.mean(np.abs(y_true - y_pred) / denom) * 100.0)


def all_metrics(y_true, y_pred) -> dict:
    return {"MAE": mae(y_true, y_pred),
            "RMSE": rmse(y_true, y_pred),
            "sMAPE (%)": smape(y_true, y_pred)}
"})
