result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/backtest.py", "content": """"Walk-forward backtest with three forecasters.

Predictors have signature f(series, t) -> forecast for series[t]. They are only
honest if they read series[:t]; the corrupt-the-future test exploits this.
"""
import numpy as np
import pandas as pd

TEST_WEEKS = 40


def naive(series: np.ndarray, t: int) -> float:
    """Random-walk / naive: last observed value."""
    return float(series[t - 1])


def seasonal_naive(series: np.ndarray, t: int, lag: int = 52) -> float:
    """Seasonal-naive: value from the same week one year earlier."""
    return float(series[t - lag])


def ewma(series: np.ndarray, t: int, alpha: float = 0.3) -> float:
    """Exponentially weighted moving average with smoothing parameter alpha."""
    s = float(series[0])
    for v in np.asarray(series[:t], dtype=float):
        s = alpha * v + (1.0 - alpha) * s
    return s


FORECASTERS = {
    "naive": naive,
    "seasonal-naive": seasonal_naive,
    "ewma-0.3": ewma,
}


def walk_forecast(df: pd.DataFrame, model) -> dict:
    """One-step-ahead expanding-window forecasts over the last TEST_WEEKS weeks."""
    y = df["revenue"].to_numpy(dtype=float)
    n = len(y)
    records = []
    for t in range(n - TEST_WEEKS, n):
        pred = model(y, t)
        records.append({
            "date": df["date"].iloc[t],
            "t": t,
            "actual": float(y[t]),
            "prediction": float(pred),
        })
    return {
        "records": records,
        "dates": [r["date"] for r in records],
        "predictions": np.array([r["prediction"] for r in records]),
        "actuals": np.array([r["actual"] for r in records]),
    }


def run_backtest(df: pd.DataFrame) -> dict:
    """Run all forecasters and attach metrics to each result."""
    from metrics import all_metrics

    results = {}
    for name, model in FORECASTERS.items():
        res = walk_forecast(df, model)
        res["model"] = name
        res["metrics"] = all_metrics(res["actuals"], res["predictions"])
        results[name] = res
    return results


if __name__ == "__main__":
    results = run_backtest(__import__("gen").generate())
    for name, res in results.items():
        m = res["metrics"]
        print(f"{name:>15}: MAE={m['MAE']:9.1f}  RMSE={m['RMSE']:9.1f}  "
              f"sMAPE={m['sMAPE (%)']:6.3f}%")
"})
print(result)

