        assert set(results[name]["metrics"]) == {"MAE", "RMSE", "sMAPE (%)"}
        assert all(np.isfinite(v) for v in results[name]["metrics"].values())


# ---------------------------------------------------------------- seasonal-naive wins RMSE

def test_seasonal_naive_wins_rmse(results):
    rmses = {name: results[name]["metrics"]["RMSE"] for name in FORECASTERS}
    sn = rmses["seasonal-naive"]
    assert sn < rmses["naive"]
    assert sn < rmses["ewma-0.3"]


# ---------------------------------------------------------------- timestamps + no lookahead

def test_every_prediction_timestamped(results):
    for name in FORECASTERS:
        records = results[name]["records"]
        assert len(records) == TEST_WEEKS
        for r in records:
            assert isinstance(r["date"], pd.Timestamp)
            assert not pd.isna(r["date"])
            assert np.isfinite(r["prediction"])
            assert r["prediction"] > 0


def test_no_lookahead_corrupt_the_future():
    """Corrupt everything at and after each forecast origin; predictions must
    be unchanged, proving the forecaster only used prior data."""
    y = generate(seed=5)["revenue"].to_numpy(dtype=float)
    n = len(y)
    corruption = 1e12
    for model in (naive, seasonal_naive, ewma):
        for t in range(n - TEST_WEEKS, n):
            clean = model(y, t)
            corrupted = y.copy()
            corrupted[t:] = corruption
            assert model(corrupted, t) == clean, (
                f"{model.__name__} at t={t} changed when the future was corrupted"
            )


