# ---------------------------------------------------------------- markdown table parses

def test_markdown_table_parses_three_model_rows_with_floats():
    text = open("backtest_report.md").read()
    rows = []
    for line in text.splitlines():
        line = line.strip()
        if not (line.startswith("|") and line.endswith("|")):
            continue
        cells = [c.strip() for c in line.strip("|").split("|")]
        if cells[0] == "model":                      # header
            continue
        if all(set(c) <= set("-: ") for c in cells):  # separator row
            continue
        rows.append(cells)

    assert len(rows) == 3
    models = {cells[0] for cells in rows}
    assert models == set(FORECASTERS)
    for cells in rows:
        assert len(cells) == 4
        for cell in cells[1:]:                       # MAE, RMSE, sMAPE
            value = float(cell)
            assert np.isfinite(value) and value >= 0


def test_report_mentions_expected_sections():
    text = open("backtest_report.md").read()
    assert "# Backtest Report" in text
    for name in FORECASTERS:
        assert re.search(rf"\|\s*{re.escape(name)}\s*\|", text)
