import numpy as np
from gen import generate
from backtest import naive, ewma, TEST_WEEKS
from metrics import rmse as RMSE

def sn_drift(s, t):
    # lag-52 seasonal naive with drift from prior year-over-year log-diffs only
    log_y = np.log(np.asarray(s[:t], dtype=float))
    if len(log_y) > 52:
        b = float(np.mean(log_y[52:] - log_y[:-52]))   # 52-week log-growth
        return float(s[t-52] * np.exp(b))
    return float(s[t-52])

for seed in (5, 7, 11, 42):
    yy = generate(seed)["revenue"].to_numpy(float)
    nn = len(yy); ts = nn-TEST_WEEKS
    r = {}
    for name, f in (("naive",naive),("sn_drift",sn_drift),("ewma",ewma)):
        p = [f(yy,t) for t in range(ts,nn)]
        r[name] = RMSE(yy[ts:], p)
    wins = r["sn_drift"] < r["naive"] and r["sn_drift"] < r["ewma"]
    print(f"seed {seed}: naive={r['naive']:7.0f}  sn_drift={r['sn_drift']:7.0f}  ewma={r['ewma']:7.0f}  -> seasonal-naive wins RMSE: {wins}")
